import{_ as e,c as l,o as i,ag as o}from"./chunks/framework.BeChtK_P.js";const u=JSON.parse('{"title":"PIKE2008 HP9212-4i(4e) SAS2008 HBA卡 UEFI Shell 刷IT直通模式教程（纯UEFI、无DOS）","description":"","frontmatter":{"title":"PIKE2008 HP9212-4i(4e) SAS2008 HBA卡 UEFI Shell 刷IT直通模式教程（纯UEFI、无DOS）","author":"welpher.yu","date":"2026-05-13T18:47:11.000Z","tags":["HBA卡"],"categories":["居家折腾"]},"headers":[],"relativePath":"posts/2026/lsi-2008-to-it-mode.md","filePath":"posts/2026/lsi-2008-to-it-mode.md"}'),s={name:"posts/2026/lsi-2008-to-it-mode.md"};function t(n,a,r,p,h,d){return i(),l("div",null,[...a[0]||(a[0]=[o(`<h2 id="一、前言" tabindex="-1">一、前言 <a class="header-anchor" href="#一、前言" aria-label="Permalink to &quot;一、前言&quot;">​</a></h2><p>华硕PIKE2008、HP 9212-4i、LSI9211-8i 全部采用 <strong>SAS2008(B2)</strong> 主控。出厂默认IR硬件RAID模式，不适合NAS、Unraid、PVE、ZFS、黑群晖直通使用。</p><p><strong>IT直通模式</strong>是存储用户最优选择：硬盘直连系统、无RAID锁、低占用、兼容性极强。</p><p>网上大部分老旧教程使用FreeDOS，需要开启CSM，新主板不兼容。本文采用<strong>Rufus官方一键下载UEFI Shell</strong>，无需手动下载Shell文件、无需手动改文件名，目前最简单、零出错刷卡方案。</p><h2 id="二、适配卡片清单" tabindex="-1">二、适配卡片清单 <a class="header-anchor" href="#二、适配卡片清单" aria-label="Permalink to &quot;二、适配卡片清单&quot;">​</a></h2><ul><li><p>华硕 PIKE 2008</p></li><li><p>HP LSI 9212-4i / 9212-4i4e</p></li><li><p>LSI 9211-8i</p></li><li><p>所有 SAS2008 系列 HBA 阵列卡</p></li></ul><h2 id="三、所需文件-官方下载地址" tabindex="-1">三、所需文件 + 官方下载地址 <a class="header-anchor" href="#三、所需文件-官方下载地址" aria-label="Permalink to &quot;三、所需文件 \\+ 官方下载地址&quot;">​</a></h2><blockquote><p><strong>重点：UEFI 必须使用 .efi 文件，不要使用DOS版exe。</strong></p></blockquote><h3 id="_3-1-文件清单" tabindex="-1">3.1 文件清单 <a class="header-anchor" href="#_3-1-文件清单" aria-label="Permalink to &quot;3\\.1 文件清单&quot;">​</a></h3><ol><li><p><strong>sas2flash.efi</strong>（UEFI专用刷机工具）</p></li><li><p><strong>214i4et.bin</strong>（SAS2008 IT固件）</p></li><li><p><strong>mptsas2.rom</strong>（卡引导ROM）</p></li></ol><h3 id="_3-2-官方下载地址" tabindex="-1">3.2 官方下载地址 <a class="header-anchor" href="#_3-2-官方下载地址" aria-label="Permalink to &quot;3\\.2 官方下载地址&quot;">​</a></h3><ul><li><strong>9212 4i4e Broadcom官方固件包（含bin+rom）</strong> 直链：<code>https://docs\\.broadcom\\.com/docs/9212\\_4i4e\\_Package\\_P20\\_IR\\_IT\\_FW\\_BIOS\\_for\\_MSDOS\\_Windows\\.zip</code> 解压提取： IT固件：<code>Firmware\\\\HBA\\_9212\\_4i4e\\_IT\\\\214i4et\\.bin</code> ROM文件：<code>sasbios\\_rel\\\\mptsas2\\.rom</code> 其它版本一定要去找自己卡的版本，不然会有问题</li></ul><h2 id="四、rufus-一键制作-uefi-shell-启动盘-当前最简正确方法" tabindex="-1">四、Rufus 一键制作 UEFI Shell 启动盘（当前最简正确方法） <a class="header-anchor" href="#四、rufus-一键制作-uefi-shell-启动盘-当前最简正确方法" aria-label="Permalink to &quot;四、Rufus 一键制作 UEFI Shell 启动盘（当前最简正确方法）&quot;">​</a></h2><p><strong>纠正网上错误：新版Rufus 可以直接下载 UEFI Shell，不需要手动下载efi、不需要手动新建EFI文件夹。</strong></p><h3 id="_4-1-rufus-参数设置-照抄即可" tabindex="-1">4.1 Rufus 参数设置（照抄即可） <a class="header-anchor" href="#_4-1-rufus-参数设置-照抄即可" aria-label="Permalink to &quot;4\\.1 Rufus 参数设置（照抄即可）&quot;">​</a></h3><ul><li><p>设备：选择你的U盘（≥1GB）</p></li><li><p><strong>引导选择：下载 UEFI Shell</strong>（重点！不要选FreeDOS、不要选非可引导，一般来说下载2.0版本就行）</p></li><li><p>版本：选择 <strong>x64</strong></p></li><li><p>分区方案：<strong>GPT</strong></p></li><li><p>目标系统：<strong>UEFI（非CSM）</strong></p></li><li><p>文件系统：<strong>FAT32</strong></p></li></ul><h3 id="_4-2-制作流程" tabindex="-1">4.2 制作流程 <a class="header-anchor" href="#_4-2-制作流程" aria-label="Permalink to &quot;4\\.2 制作流程&quot;">​</a></h3><ol><li><p>点击右下角<strong>开始</strong>。</p></li><li><p>弹窗确认，Rufus自动下载官方纯净UEFI Shell并写入U盘。</p></li><li><p>等待制作完成，无需任何手动改文件、改目录。</p></li></ol><h3 id="_4-3-放入刷机文件" tabindex="-1">4.3 放入刷机文件 <a class="header-anchor" href="#_4-3-放入刷机文件" aria-label="Permalink to &quot;4\\.3 放入刷机文件&quot;">​</a></h3><p>制作完成后，把以下三个文件<strong>直接复制到U盘根目录</strong>：</p><ul><li><p>sas2flash.efi</p></li><li><p>214i4et.bin</p></li><li><p>mptsas2.rom</p></li></ul><h2 id="五、主板bios设置" tabindex="-1">五、主板BIOS设置 <a class="header-anchor" href="#五、主板bios设置" aria-label="Permalink to &quot;五、主板BIOS设置&quot;">​</a></h2><ol><li><p>开机按 <code>Del / F2</code> 进入BIOS</p></li><li><p><strong>关闭 CSM 兼容模块</strong></p></li><li><p><strong>关闭 Secure Boot 安全启动</strong></p></li><li><p>启动模式改为：<strong>UEFI Only</strong></p></li><li><p>第一启动项选择：UEFI U盘</p></li><li><p>保存重启</p></li></ol><h2 id="六、uefi-shell-刷卡流程-顺序绝对不能乱" tabindex="-1">六、UEFI Shell 刷卡流程（顺序绝对不能乱） <a class="header-anchor" href="#六、uefi-shell-刷卡流程-顺序绝对不能乱" aria-label="Permalink to &quot;六、UEFI Shell 刷卡流程（顺序绝对不能乱）&quot;">​</a></h2><h3 id="_6-1-进入u盘" tabindex="-1">6.1 进入U盘 <a class="header-anchor" href="#_6-1-进入u盘" aria-label="Permalink to &quot;6\\.1 进入U盘&quot;">​</a></h3><p>开机自动进入Shell，输入命令：</p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fs0:</span></span>
<span class="line"><span>dir</span></span></code></pre></div><p>找不到就试 <code>fs1:</code>、<code>fs2:</code>，能看到刷机文件即为正确盘符。</p><h3 id="_6-2-刷写命令-逐条执行-等跑完再下一条" tabindex="-1">6.2 刷写命令（逐条执行，等跑完再下一条） <a class="header-anchor" href="#_6-2-刷写命令-逐条执行-等跑完再下一条" aria-label="Permalink to &quot;6\\.2 刷写命令（逐条执行，等跑完再下一条）&quot;">​</a></h3><h4 id="_1-彻底擦除原厂ir固件" tabindex="-1">① 彻底擦除原厂IR固件 <a class="header-anchor" href="#_1-彻底擦除原厂ir固件" aria-label="Permalink to &quot;① 彻底擦除原厂IR固件&quot;">​</a></h4><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sas2flash.efi -o -e 7</span></span></code></pre></div><p>⚠️ 执行后卡片变成裸卡、无固件、提示不可用，属于正常现象。</p><h4 id="_2-写入it固件-rom" tabindex="-1">② 写入IT固件+ROM <a class="header-anchor" href="#_2-写入it固件-rom" aria-label="Permalink to &quot;② 写入IT固件\\+ROM&quot;">​</a></h4><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sas2flash.efi -o -f 214i4et.bin -b mptsas2.rom</span></span></code></pre></div><p>出现 <strong>Finished Processing Commands Successfully</strong> 代表刷写成功。</p><h4 id="_3-重启-必须重启" tabindex="-1">③ 重启（必须重启！） <a class="header-anchor" href="#_3-重启-必须重启" aria-label="Permalink to &quot;③ 重启（必须重启！）&quot;">​</a></h4><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>reset</span></span></code></pre></div><p>重启再次进入UEFI Shell，此时卡片固件恢复正常。</p><h4 id="_4-写入原厂sas地址-防掉盘" tabindex="-1">④ 写入原厂SAS地址（防掉盘） <a class="header-anchor" href="#_4-写入原厂sas地址-防掉盘" aria-label="Permalink to &quot;④ 写入原厂SAS地址（防掉盘）&quot;">​</a></h4><p>查看卡背面贴纸，以 <code>500605B0</code> 开头，去掉横杠空格。</p><div class="language-Plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">Plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sas2flash.efi -o -sasadd 500605B0XXXXXXXX</span></span></code></pre></div><h2 id="七、验证是否刷写成功" tabindex="-1">七、验证是否刷写成功 <a class="header-anchor" href="#七、验证是否刷写成功" aria-label="Permalink to &quot;七、验证是否刷写成功&quot;">​</a></h2><ol><li><p>拔掉U盘，正常开机。</p></li><li><p>开机自检观察LSI SAS2008信息。</p></li><li><p><strong>PRODUCT IDENTIFIER 显示 SAS2008-IT 即为成功。</strong></p></li></ol><h2 id="八、常见报错说明" tabindex="-1">八、常见报错说明 <a class="header-anchor" href="#八、常见报错说明" aria-label="Permalink to &quot;八、常见报错说明&quot;">​</a></h2><h3 id="报错-controller-is-not-operational" tabindex="-1">报错：Controller is not operational <a class="header-anchor" href="#报错-controller-is-not-operational" aria-label="Permalink to &quot;报错：Controller is not operational&quot;">​</a></h3><p>原因：执行完 <code>\\-e 7</code> 擦除，卡片无固件。</p><p>解决：先刷固件 → 重启 → 再写SAS地址，顺序不可逆。</p><h3 id="报错-file-not-found" tabindex="-1">报错：File not found <a class="header-anchor" href="#报错-file-not-found" aria-label="Permalink to &quot;报错：File not found&quot;">​</a></h3><p>文件不在根目录、文件名写错、U盘非FAT32格式。</p><h2 id="九、硬性注意事项" tabindex="-1">九、硬性注意事项 <a class="header-anchor" href="#九、硬性注意事项" aria-label="Permalink to &quot;九、硬性注意事项&quot;">​</a></h2><ul><li><p>刷写全程<strong>禁止断电、强制重启</strong>，会直接变砖。</p></li><li><p>不要乱填SAS地址，必须使用卡片原厂地址。</p></li><li><p>本教程为纯正UEFI，适配所有新主板，不兼容老旧CSM方案。</p></li></ul>`,51)])])}const b=e(s,[["render",t]]);export{u as __pageData,b as default};
